# --- quotas ---------------------------------------------------------

@staticmethod
def _parse_quota_growth(raw: Any, limits: dict[str, int]) -> dict[str, dict[str, int]]:
    """Validate the optional growth policy of a quota declaration.

    The policy names only the resources it covers; a resource it omits is
    never auto-raised. Each named resource must declare exactly a positive
    integer ``step`` and a positive integer ``cap`` no lower than the
    resource's declared limit.
    """
    if not isinstance(raw, dict):
        raise ValidationError("quota growth must be an object")
    if not raw or set(raw) - set(QUOTA_RESOURCES):
        raise ValidationError("quota growth must name only workflows and executions")
    policy: dict[str, dict[str, int]] = {}
    for kind in QUOTA_RESOURCES:
        if kind not in raw:
            continue
        entry = raw[kind]
        if not isinstance(entry, dict) or set(entry) != {"step", "cap"}:
            raise ValidationError(f"quota growth {kind} must contain exactly step and cap")
        values: dict[str, int] = {}
        for field in ("step", "cap"):
            value = entry[field]
            if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
                raise ValidationError(f"quota growth {kind} {field} must be a positive integer")
            values[field] = value
        if values["cap"] < limits[kind]:
            raise ValidationError(f"quota growth {kind} cap must not be below the declared limit")
        policy[kind] = values
    return policy

def declare_quota(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    if not isinstance(raw, dict) or not {"workflows", "executions"} <= set(raw) <= {
        "workflows",
        "executions",
        "growth",
    }:
        raise ValidationError("quota must contain exactly workflows and executions, and optionally growth")
    limits = {}
    for field in ("workflows", "executions"):
        value = raw[field]
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"quota {field} must be a positive integer")
        if value <= 0:
            raise ValidationError(f"quota {field} must be a positive integer")
        limits[field] = value
    # The growth policy is optional; a declaration without one is exactly
    # the two-limit request and removes any policy the tenant had, since a
    # repeated declaration replaces limits and policy as a whole.
    policy = self._parse_quota_growth(raw["growth"], limits) if "growth" in raw else {}

    def apply() -> dict[str, Any]:
        self.store.connection.execute(
            "INSERT INTO quotas(tenant, workflows, executions, "
            "workflows_step, workflows_cap, executions_step, executions_cap, updated_at) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(tenant) DO UPDATE SET workflows = excluded.workflows, "
            "executions = excluded.executions, workflows_step = excluded.workflows_step, "
            "workflows_cap = excluded.workflows_cap, executions_step = excluded.executions_step, "
            "executions_cap = excluded.executions_cap, updated_at = excluded.updated_at",
            (
                tenant,
                limits["workflows"],
                limits["executions"],
                policy.get("workflows", {}).get("step"),
                policy.get("workflows", {}).get("cap"),
                policy.get("executions", {}).get("step"),
                policy.get("executions", {}).get("cap"),
                self.store.now(),
            ),
        )
        return self._quota_declaration(limits, policy)

    with self._operation():
        return self._idempotent(key, "declare-quota", apply, tenant)

@staticmethod
def _quota_declaration(
    limits: dict[str, int], policy: dict[str, dict[str, int]]
) -> dict[str, Any]:
    """Render a declaration response (and a stored row back) in stable key order."""
    quota: dict[str, Any] = {"workflows": limits["workflows"], "executions": limits["executions"]}
    if policy:
        # The policy names only the resources the declaration covered,
        # workflows before executions, and within each entry step then cap.
        growth = {
            kind: {"step": policy[kind]["step"], "cap": policy[kind]["cap"]}
            for kind in QUOTA_RESOURCES
            if kind in policy
        }
        quota["growth"] = growth
    return {"quota": quota}

@staticmethod
def _row_policy(row: Any) -> dict[str, dict[str, int]]:
    """Collect the growth policy carried by a quotas row, omitting unmanaged resources."""
    policy: dict[str, dict[str, int]] = {}
    for kind in QUOTA_RESOURCES:
        step, cap = row[f"{kind}_step"], row[f"{kind}_cap"]
        if step is not None and cap is not None:
            policy[kind] = {"step": step, "cap": cap}
    return policy

def get_quota(self, tenant: str) -> dict[str, Any]:
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    with self._operation():
        with self.store.transaction():
            row = self.store.connection.execute(
                "SELECT workflows, executions, workflows_step, workflows_cap, "
                "executions_step, executions_cap FROM quotas WHERE tenant = ?",
                (tenant,),
            ).fetchone()
            if row is None:
                return {"quota": None}
            limits = {"workflows": row["workflows"], "executions": row["executions"]}
            return self._quota_declaration(limits, self._row_policy(row))

def quota_status(self, tenant: str) -> dict[str, Any]:
    """Report each limited resource's declared limit, current holding, and remaining room.

    Read-only: it writes no metering record and changes no declared quota,
    usage, bill, schedule, approval, or replay conclusion. The holding is
    the same real count the quota decision uses (a row count for the
    tenant); the remaining room is limit minus holding, reported truthfully
    as a negative number when a limit was lowered below the current holding
    instead of being clamped to zero. Resources appear workflows first and
    executions second. A tenant that has declared no quota gets the
    definite empty result ``{"status": null}`` — neither resource is listed.
    Another tenant's quota and holdings are never visible.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    with self._operation():
        with self.store.transaction():
            limits = self._quota_limits(tenant)
            if limits is None:
                return {"status": None}
            status = {}
            for kind in QUOTA_RESOURCES:
                ceiling = limits[kind]
                held = self.store.connection.execute(
                    f"SELECT COUNT(*) AS held FROM {kind} WHERE tenant = ?",
                    (tenant,),
                ).fetchone()["held"]
                status[kind] = {"limit": ceiling, "held": held, "remaining": ceiling - held}
            return {"status": status}

def delete_quota(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    """Remove the tenant's declared quota as a whole.

    The body must be an empty object; deleting the quota of a tenant that
    never declared one is the same definite empty result as deleting one
    it held. After the delete the tenant holds no declared limits, so both
    quota reads report the never-declared empty results and later writes
    run without quota checks. Existing workflows and executions are not
    deleted or made unusable, recorded usage counts and bill conclusions
    are untouched, and the delete itself writes no metering record. The
    route requires a tenant and an idempotency key: repeating the same
    delete with the same key returns the first result without a second
    effect, while the same key on another operation is the usual 409
    conflict and leaves every declaration in place.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    self._empty_body(raw, "delete quota")

    def apply() -> dict[str, Any]:
        # Removing a declaration that was never made deletes no row but
        # is still the same definite empty result, never an error.
        self.store.connection.execute(
            "DELETE FROM quotas WHERE tenant = ?",
            (tenant,),
        )
        return {"quota": None}

    with self._operation():
        return self._idempotent(key, "delete-quota", apply, tenant)

def declare_prices(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    """Declare the tenant's price table, replacing it as a whole.

    The body is a JSON object whose keys name metered types and whose
    values are positive integer-cent prices. A type the table omits keeps
    the built-in default price. A non-object body, a missing or unknown
    field, or a non-positive, non-integer, boolean, or non-finite price is
    a validation error that writes nothing. The route requires a tenant
    and an idempotency key; repeating the same declaration with the same
    key returns the first result without a second replacement, while the
    same key on another operation is the usual 409 conflict.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    if not isinstance(raw, dict) or not raw:
        raise ValidationError("prices must be a non-empty object of metered types to positive integer prices")
    prices: dict[str, int] = {}
    for usage_type, value in raw.items():
        if usage_type not in USAGE_TYPES:
            raise ValidationError(f"unknown metered type: {usage_type}")
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"price for {usage_type} must be a positive integer")
        if value <= 0:
            raise ValidationError(f"price for {usage_type} must be a positive integer")
        prices[usage_type] = value
    document = self.store.encode(prices)

    def apply() -> dict[str, Any]:
        # The history record shares the change's effective timestamp and
        # commits in the same transaction, so a reader always sees the
        # table and its history agree.
        occurred_at = self.store.now()
        self.store.connection.execute(
            "INSERT INTO prices(tenant, document, updated_at) VALUES (?, ?, ?) "
            "ON CONFLICT(tenant) DO UPDATE SET document = excluded.document, "
            "updated_at = excluded.updated_at",
            (tenant, document, occurred_at),
        )
        snapshot = dict(sorted(prices.items()))
        self._record_price_history(tenant, PRICE_ACTION_DECLARE, snapshot, occurred_at)
        return {"prices": snapshot}

    with self._operation():
        return self._idempotent(key, "declare-prices", apply, tenant)

def delete_prices(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    """Remove the tenant's declared price table as a whole.

    The body must be an empty object; deleting a table that was never
    declared is the same definite empty result as deleting one that was.
    After the delete the tenant holds no table of its own, so later bills
    use the built-in defaults; recorded usage and bills already taken are
    untouched. The route requires a tenant and an idempotency key:
    repeating the same delete with the same key returns the first result
    without a second effect, while the same key on another operation is
    the usual 409 conflict and leaves every table in place.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    self._empty_body(raw, "delete prices")

    def apply() -> dict[str, Any]:
        # Removing a table that was never declared deletes no row but is
        # still the same definite empty result, never an error; the delete
        # itself still takes effect, so it leaves its own history record.
        occurred_at = self.store.now()
        self.store.connection.execute(
            "DELETE FROM prices WHERE tenant = ?",
            (tenant,),
        )
        self._record_price_history(tenant, PRICE_ACTION_DELETE, None, occurred_at)
        return {"prices": None}

    with self._operation():
        return self._idempotent(key, "delete-prices", apply, tenant)

def _declared_prices(self, tenant: str) -> dict[str, int] | None:
    """Return the tenant's declared price table, or None when it never declared one."""
    row = self.store.connection.execute(
        "SELECT document FROM prices WHERE tenant = ?",
        (tenant,),
    ).fetchone()
    if row is None:
        return None
    return self.store.decode(row["document"])

def get_prices(self, tenant: str) -> dict[str, Any]:
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    with self._operation():
        with self.store.transaction():
            declared = self._declared_prices(tenant)
            if declared is None:
                return {"prices": None}
            return {"prices": dict(sorted(declared.items()))}

def price_history(
    self,
    tenant: str,
    actions: tuple[str, ...] | None = None,
    since: datetime | None = None,
    until: datetime | None = None,
    cursor: int | None = None,
    limit: int | None = None,
) -> dict[str, Any]:
    """Return the tenant's price-table change history, filtered and paged.

    The query is read-only: it appends no history, writes no table, and
    changes no metering, usage, bill, or quota conclusion. Records come
    back in ascending occurrence-time order, with records sharing one
    instant ordered by ascending sequence. ``actions`` keeps only records
    whose action is in the set; ``since`` and ``until`` bind a closed
    interval on each record's own occurrence time (a window with ``since``
    later than ``until`` simply matches nothing); ``cursor`` keeps only
    records with a sequence strictly greater than it; ``limit`` caps the
    page at that many records. Filters combine as an intersection and
    sequences are never renumbered, so consecutive pages neither overlap
    nor skip. A tenant with no matching records gets the definite empty
    list, and another tenant's history is never visible.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    wanted = set(actions) if actions is not None else None
    with self._operation():
        with self.store.transaction():
            rows = self.store.connection.execute(
                "SELECT sequence, action, snapshot, occurred_at FROM price_history WHERE tenant = ?",
                (tenant,),
            ).fetchall()
            hits = []
            for row in rows:
                if wanted is not None and row["action"] not in wanted:
                    continue
                occurred_at = _parse_stored_time(row["occurred_at"])
                if not self._within_window(occurred_at, since, until):
                    continue
                if cursor is not None and row["sequence"] <= cursor:
                    continue
                hits.append((occurred_at, row))
            hits.sort(key=lambda hit: (hit[0], hit[1]["sequence"]))
            if limit is not None:
                hits = hits[:limit]
            records = []
            for _, row in hits:
                if row["snapshot"] is None:
                    snapshot = None
                else:
                    # A declaration's snapshot lists only the named types,
                    # in ascending type-identifier order.
                    snapshot = dict(sorted(self.store.decode(row["snapshot"]).items()))
                records.append(
                    {
                        "sequence": row["sequence"],
                        "action": row["action"],
                        "occurred_at": row["occurred_at"],
                        "snapshot": snapshot,
                    }
                )
            return {"history": records}

def _effective_prices(self, tenant: str) -> dict[str, int]:
    """Prices in effect for the tenant at query time.

    Declared prices override the built-in defaults per named metered type;
    a type the declaration leaves out keeps its default. Read at query
    time on the open transaction, so a later declaration never changes a
    bill already taken and never rewrites recorded usage.

    "node_completed",
    "node_failed",
    "node_retried",
    "node_skipped",
    "version_migrated",
)


def _parse_timestamp(value: str | None, field: str) -> datetime | None:
    """Parse an ISO-8601 UTC timestamp ending in Z; absent means no boundary."""
    if value is None:
        return None
    if not isinstance(value, str) or not value.endswith("Z"):
        raise ValidationError(f"{field} must be an ISO-8601 UTC timestamp ending in Z")
    try:
        parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    except ValueError as error:
        raise ValidationError(f"{field} must be an ISO-8601 UTC timestamp ending in Z") from error
    return parsed


def _parse_stored_time(value: str) -> datetime:
    """Parse a timestamp the service itself stored (always a UTC value ending in Z)."""
    return datetime.fromisoformat(value[:-1] + "+00:00")


def _iso_utc(epoch_seconds: float) -> str:
    """Render epoch seconds as an ISO-8601 UTC timestamp string ending in Z."""
    return datetime.fromtimestamp(epoch_seconds, timezone.utc).isoformat().replace("+00:00", "Z")


def _bucket_start(occurred_at: datetime, bucket: str) -> datetime:
    """Floor a UTC timestamp to the start of its fixed time bucket.

    ``hour`` aligns to the UTC hour and ``day`` to UTC midnight; both drop the
    finer fields rather than shifting any instant, so UTC alignment never
    depends on the caller's locale.
    """
    if bucket == USAGE_BUCKET_HOUR:
        return occurred_at.replace(minute=0, second=0, microsecond=0)
    return occurred_at.replace(hour=0, minute=0, second=0, microsecond=0)


def _format_bucket_start(start: datetime) -> str:
    """Render a bucket start as the stored ISO-8601 UTC form ending in Z."""
    return start.isoformat().replace("+00:00", "Z")


def _prometheus_label(value: str) -> str:
    """Escape a label value for the Prometheus text exposition format."""
    return value.replace("\\", "\\\\").replace("\n", "\\n").replace('"', '\\"')


def _json_type(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"

class ChronicleFlowError(Exception):
    code = "internal_error"
    status = 500


class ValidationError(ChronicleFlowError):
    code = "validation_error"
    status = 400


class NotFoundError(ChronicleFlowError):
    code = "not_found"
    status = 404


class ConflictError(ChronicleFlowError):
    code = "conflict"
    status = 409

